:root {
  --bg-card: #1c1410;
  --bg-header: #2a1f18;
  --bg-stat: #231a13;
  --bg-stat-highlight: #7c3d11;
  --bg-entry: #241c15;
  --border-main: #3d2c1e;
  --border-subtle: #2e2218;
  --accent-orange: #e8762a;
  --accent-gold: #c9933a;
  --accent-cream: #f0e0c8;
  --text-primary: #f0e0c8;
  --text-secondary: #a07850;
  --text-muted: #6b4e34;
  --tag-done-bg: #1a3d1a;
  --tag-done-text: #6fcf6f;
  --tag-warn-bg: #3d3210;
  --tag-warn-text: #e8c84a;
  --tag-overdue-bg: #3d1212;
  --tag-overdue-text: #e86a6a;
  --dot-warn: #e8c84a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.service-log {
  width: 460px;
  background-color: var(--bg-card);
  border: 1px solid var(--border-main);
  border-radius: 12px;
  overflow: hidden;
}

.log-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg-header);
  padding: 9px 13px;
  border-bottom: 1px solid var(--border-main);
}

.machine-info {
  display: flex;
  align-items: center;
  gap: 8px;
}

.machine-badge {
  font-size: 22px;
  line-height: 1;
  background-color: var(--bg-stat);
  border: 1px solid var(--border-main);
  border-radius: 7px;
  padding: 4px 6px;
}

.machine-meta {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.machine-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.machine-id {
  font-size: 10px;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.service-status {
  display: flex;
  align-items: center;
  gap: 5px;
  background-color: var(--tag-warn-bg);
  border: 1px solid var(--tag-warn-text);
  border-radius: 20px;
  padding: 3px 9px;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--dot-warn);
}

.status-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--tag-warn-text);
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-bottom: 1px solid var(--border-main);
}

.stat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 7px 4px;
  background-color: var(--bg-stat);
  border-right: 1px solid var(--border-subtle);
  gap: 1px;
}

.stat-card:last-child {
  border-right: none;
}

.stat-card.highlight {
  background-color: var(--bg-stat-highlight);
}

.stat-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--accent-cream);
  line-height: 1;
}

.stat-card.highlight .stat-value {
  color: #ffffff;
}

.stat-label {
  font-size: 10px;
  color: var(--text-muted);
  text-align: center;
}

.log-entries {
  padding: 8px 13px;
}

.section-title {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin: 0 0 6px 0;
}

.entry-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.entry {
  display: flex;
  align-items: center;
  gap: 7px;
  background-color: var(--bg-entry);
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  padding: 6px 8px;
}

.entry--done {
  border-left: 3px solid var(--tag-done-text);
}

.entry--warn {
  border-left: 3px solid var(--tag-warn-text);
}

.entry--overdue {
  border-left: 3px solid var(--tag-overdue-text);
}

.entry-icon {
  font-size: 13px;
  line-height: 1;
  flex-shrink: 0;
}

.entry-body {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
  min-width: 0;
}

.entry-task {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.2;
}

.entry-note {
  font-size: 10px;
  color: var(--text-muted);
  line-height: 1.2;
}

.entry-date {
  font-size: 10px;
  color: var(--text-secondary);
  font-weight: 500;
  flex-shrink: 0;
}

.entry-tag {
  font-size: 10px;
  font-weight: 700;
  border-radius: 4px;
  padding: 2px 6px;
  flex-shrink: 0;
}

.tag--done {
  background-color: var(--tag-done-bg);
  color: var(--tag-done-text);
}

.tag--warn {
  background-color: var(--tag-warn-bg);
  color: var(--tag-warn-text);
}

.tag--overdue {
  background-color: var(--tag-overdue-bg);
  color: var(--tag-overdue-text);
}

.log-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg-header);
  border-top: 1px solid var(--border-main);
  padding: 8px 13px;
}

.next-service {
  display: flex;
  align-items: center;
  gap: 6px;
}

.next-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.next-date {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-gold);
}

.footer-actions {
  display: flex;
  gap: 6px;
}

.btn {
  font-size: 11px;
  font-weight: 600;
  border: none;
  border-radius: 6px;
  padding: 6px 12px;
  cursor: pointer;
  line-height: 1;
}

.btn--secondary {
  background-color: var(--bg-stat);
  color: var(--text-secondary);
  border: 1px solid var(--border-main);
}

.btn--primary {
  background-color: var(--accent-orange);
  color: #ffffff;
}
